def transform(grid):
    from collections import deque

    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find cells that are 0 in input (only 0s get filled with 4 based on demos)
    # In tests without 0, the rule might still only apply to 0 unless otherwise specified

    # Mark all 0s connected to boundary and fill boundary-connected 0s remain 0
    # Enclosed 0s become 4

    visited = set()

    # First, find all reachable 0s from boundary using BFS
    boundary_q = deque()
    for r, c in enumerate(list(range(cols))):
        if grid[0][c] == 0:
            boundary_q.append((0, c))
            visited.add((0, c))
        if grid[rows-1][c] == 0:
            if (rows-1, c) not in visited:
                visited.add((rows-1, c))
                boundary_q.append((rows-1, c))

    for c in range(cols):
        if grid[0][c] == 0:
            visited.add((0, c))
            boundary_q.append((0, c))
        if grid[c][0] == 0:
            visited.add((c, 0))
            boundary_q.append((c, 0))

    # Concurrent BFS from all boundary 0s
    while boundary_q:
        r, c = boundary_q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    boundary_q.append((nr, nc))

    # Enclosed 0s (not in visited) become 4
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in visited:
                result[r][c] = 4

    return result
